@@ -5843,1 +5843,1 @@
-  // a += value + x + ac;
+  // a += (d ^ (b & (c ^ d))) + x + ac;
@@ -5845,4 +5845,7 @@
-  void m5_FF_GG_HH_II_epilogue(BufRegCache& reg_cache,
-                               Register a, Register b, Register c, Register d,
-                               int k, int s, int t,
-                               Register value) {
+  void md5_FF(BufRegCache& reg_cache,
+              Register a, Register b, Register c, Register d,
+              int k, int s, int t,
+              Register rtmp1, Register rtmp2) {
+    // rtmp1 = c ^ d
+    __ xorr(rtmp1, c, d);
+
@@ -5852,1 +5855,4 @@
-    // a += x;
+    // rtmp1 = b & (c ^ d) = b & rtmp1
+    __ andr(rtmp1, b, rtmp1);
+
+    // a += x
@@ -5854,2 +5860,0 @@
-    // a += value;
-    __ addw(a, a, value);
@@ -5857,1 +5861,7 @@
-    // a = Integer.rotateLeft(a, s) + b;
+    // rtmp1 = d ^ (b & (c ^ d)) = d ^ rtmp1
+    __ xorr(rtmp1, d, rtmp1);
+
+    // a += rtmp1
+    __ addw(a, a, rtmp1);
+
+    // a = Integer.rotateLeft(a, s) + b
@@ -5862,1 +5872,1 @@
-  // a += ((b & c) | ((~b) & d)) + x + ac;
+  // a += ((c & (~d)) + (b & d)) + x + ac;
@@ -5864,1 +5874,1 @@
-  void md5_FF(BufRegCache& reg_cache,
+  void md5_GG(BufRegCache& reg_cache,
@@ -5868,2 +5878,3 @@
-    // rtmp1 = b & c
-    __ andr(rtmp1, b, c);
+    // a += x + ac
+    reg_cache.add_u32(a, k);
+    __ addw(a, a, t, t1);
@@ -5871,2 +5882,2 @@
-    // rtmp2 = (~b) & d
-    __ andn(rtmp2, d, b);
+    // rtmp1 = c & (~d)
+    __ andn(rtmp1, c, d);
@@ -5874,2 +5885,2 @@
-    // rtmp1 = (b & c) | ((~b) & d)
-    __ orr(rtmp1, rtmp1, rtmp2);
+    // rtmp2 = b & d
+    __ andr(rtmp2, b, d);
@@ -5877,2 +5888,2 @@
-    m5_FF_GG_HH_II_epilogue(reg_cache, a, b, c, d, k, s, t, rtmp1);
-  }
+    // a += c & (~d)
+    __ addw(a, a, rtmp1);
@@ -5880,8 +5891,2 @@
-  // a += ((b & d) | (c & (~d))) + x + ac;
-  // a = Integer.rotateLeft(a, s) + b;
-  void md5_GG(BufRegCache& reg_cache,
-              Register a, Register b, Register c, Register d,
-              int k, int s, int t,
-              Register rtmp1, Register rtmp2) {
-    // rtmp1 = b & d
-    __ andr(rtmp1, b, d);
+    // a += b & d
+    __ addw(a, a, rtmp2);
@@ -5889,7 +5894,3 @@
-    // rtmp2 = c & (~d)
-    __ andn(rtmp2, c, d);
-
-    // rtmp1 = (b & d) | (c & (~d))
-    __ orr(rtmp1, rtmp1, rtmp2);
-
-    m5_FF_GG_HH_II_epilogue(reg_cache, a, b, c, d, k, s, t, rtmp1);
+    // a = Integer.rotateLeft(a, s) + b
+    __ rolw(a, a, s);
+    __ addw(a, a, b);
@@ -5898,1 +5899,1 @@
-  // a += ((b ^ c) ^ d) + x + ac;
+  // a += (b ^ (c ^ d)) + x + ac;
@@ -5904,3 +5905,14 @@
-    // rtmp1 = (b ^ c) ^ d
-    __ xorr(rtmp2, b, c);
-    __ xorr(rtmp1, rtmp2, d);
+    // precomputed rtmp2 = (c ^ d)
+    // rtmp1 = b ^ (c ^ d) = b ^ rtmp2
+    __ xorr(rtmp1, b, rtmp2);
+
+    // a += x + ac
+    reg_cache.add_u32(a, k);
+    __ addw(a, a, t, t1);
+
+    // rtmp2 = b ^ (c ^ d) ^ d == (b ^ c)
+    // rtmp2 will be next round's (c ^ d)
+    __ xorr(rtmp2, rtmp1, d);
+
+    // a += rtmp1
+    __ addw(a, a, rtmp1);
@@ -5908,1 +5920,3 @@
-    m5_FF_GG_HH_II_epilogue(reg_cache, a, b, c, d, k, s, t, rtmp1);
+    // a = Integer.rotateLeft(a, s) + b
+    __ rolw(a, a, s);
+    __ addw(a, a, b);
@@ -5917,0 +5931,4 @@
+    // a += x + ac
+    reg_cache.add_u32(a, k);
+    __ addw(a, a, t, t1);
+
@@ -5921,1 +5939,6 @@
-    m5_FF_GG_HH_II_epilogue(reg_cache, a, b, c, d, k, s, t, rtmp1);
+    // a += rtmp1
+    __ addw(a, a, rtmp1);
+
+    // a = Integer.rotateLeft(a, s) + b
+    __ rolw(a, a, s);
+    __ addw(a, a, b);
@@ -6125,0 +6148,2 @@
+    // pre-compute (c ^ d) for the first HH round.
+    __ xorr(rtmp2, c, d);
